   {tab==="reports"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:22}}>
    <h2 style={{fontSize:19,marginTop:0}}>التقارير والإحصائيات</h2><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(160px,1fr))",gap:12}}>{[["إجمالي العملاء",consoleData.metrics?.tenants||stores.length],["العملاء الفعّالون",consoleData.metrics?.activeTenants||0],["اشتراكات تنتهي خلال 30 يوم",consoleData.metrics?.expiringSoon||0],["إجمالي الطلبات",consoleData.metrics?.orders||0],["إجمالي المبيعات المسجلة",Number(consoleData.metrics?.revenue||0).toFixed(2)+" JOD"],["مبيعات آخر 30 يوم",Number(consoleData.metrics?.last30DaysRevenue||0).toFixed(2)+" JOD"],["طلبات آخر 30 يوم",consoleData.metrics?.last30DaysOrders||0],["الأصناف المنشورة",consoleData.metrics?.products||0]].map(([k,v])=><div key={String(k)} style={{padding:16,border:"1px solid #e8edf0",borderRadius:13}}><div style={{fontSize:12,color:"#8290a3"}}>{k}</div><b style={{fontSize:23,display:"block",marginTop:10}}>{v}</b></div>)}</div><p style={{fontSize:12,color:"#9a6b2d",marginTop:16}}>ملاحظة: الإيرادات محسوبة من إجمالي الطلبات المسجلة حالياً، وليست فواتير اشتراكات المنصة. تتبّع مشاهدات المنيو ومسح QR غير مفعّل بعد.</p>
   </section>}
   {tab==="users"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:22}}><h2 style={{fontSize:19,marginTop:0}}>المستخدمون والصلاحيات</h2><p style={{fontSize:13,color:"#8290a3",lineHeight:1.8}}>الحسابات الموجودة حالياً هي حسابات أدمن المتاجر، إضافة إلى حساب السوبر أدمن. نظام الموظفين ومصفوفة الصلاحيات و2FA لم يتم تفعيله بعد، لذلك لا نعرض صلاحيات شكلية غير مطبّقة.</p>{stores.map(s=><div key={s.slug} style={{display:"flex",justifyContent:"space-between",gap:10,padding:12,borderBottom:"1px solid #edf0f4"}}><b>{s.name}</b><span style={{fontSize:12,color:"#8290a3"}}>{s.adminUsername||"بدون مستخدم"} · أدمن متجر</span></div>)}</section>}
   {tab==="support"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:22}}><h2 style={{fontSize:19,marginTop:0}}>تذاكر الدعم الفني</h2><p style={{fontSize:12,color:"#8290a3"}}>هذه القائمة تعرض التذاكر الواردة عند ربط نموذج الدعم من لوحات العملاء.</p>{(consoleData.tickets||[]).length?(consoleData.tickets||[]).map((t:any)=><div key={t._id} style={{padding:13,border:"1px solid #e8edf0",borderRadius:12,marginTop:10}}><b>{t.subject||"طلب دعم"}</b><p style={{fontSize:12,color:"#657386"}}>{t.message}</p><small>{t.slug} · {t.status}</small></div>):<div style={{padding:22,textAlign:"center",background:"#f8fafb",borderRadius:12,color:"#8290a3"}}>لا توجد تذاكر محفوظة حالياً. نموذج فتح التذكرة من حساب العميل لم يتم ربطه بعد.</div>}</section>}
   {tab==="announcements"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:22,maxWidth:900}}><h2 style={{fontSize:19,marginTop:0}}>إعلانات المنصة</h2><div style={{display:"grid",gap:12}}><label><span style={label}>عنوان الإعلان</span><input style={field} value={announcementForm.title} onChange={e=>AF({...announcementForm,title:e.target.value})}/></label><label><span style={label}>نص الإعلان</span><textarea style={{...field,minHeight:110}} value={announcementForm.message} onChange={e=>AF({...announcementForm,message:e.target.value})}/></label></div><button disabled={busy} onClick={async()=>{B(true);E("");N("");try{const r=await fetch("/api/platform/console",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"announcement",...announcementForm})});const d=await r.json();if(!r.ok)throw new Error(d.error);AF({title:"",message:""});N("تم حفظ الإعلان");await load()}catch(e:any){E(e.message||"تعذر حفظ الإعلان")}finally{B(false)}}} style={{marginTop:14,padding:"11px 17px",border:0,borderRadius:10,background:"#124B32",color:"#fff",fontWeight:800}}>نشر الإعلان</button><div style={{display:"grid",gap:10,marginTop:20}}>{(consoleData.announcements||[]).map((a:any)=><div key={a._id} style={{padding:13,border:"1px solid #e8edf0",borderRadius:12}}><div style={{display:"flex",justifyContent:"space-between",gap:10}}><b>{a.title}</b><span style={{fontSize:11,color:a.active?"#267448":"#a0a9b4"}}>{a.active?"منشور":"موقوف"}</span></div><p style={{fontSize:12,lineHeight:1.8,color:"#657386"}}>{a.message}</p><button onClick={async()=>{await fetch("/api/platform/console",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"announcement",id:a._id,active:!a.active})});await load()}} style={{padding:"7px 10px",border:"1px solid #e1e8e4",borderRadius:8,background:"#fff"}}>{a.active?"إيقاف الإعلان":"تفعيل الإعلان"}</button></div>)}</div></section>}
   {tab==="activity"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:20}}><h2 style={{fontSize:18,marginTop:0}}>سجل نشاط المنصة</h2>{activity.map((a,i)=><div key={a._id||i} style={{display:"flex",gap:12,padding:"13px 0",borderBottom:"1px solid #eef1f5"}}><div style={{width:34,height:34,borderRadius:10,background:"#f5ead9",display:"grid",placeItems:"center",color:"#9a6b2d"}}><Activity size={16}/></div><div><b style={{fontSize:13}}>{a.storeName||a.slug||"المنصة"}</b><div style={{fontSize:12,color:"#77859a",marginTop:4}}>{a.type==="subscription_renewed"?"تجديد اشتراك":a.type==="store_created"?"إنشاء متجر":"تعديل بيانات المتجر"}</div><small style={{color:"#9aa5b5"}}>{a.createdAt?new Date(a.createdAt).toLocaleString("ar-JO"):""}</small></div></div>)}{!activity.length&&<p style={{color:"#8290a3"}}>لا يوجد نشاط مسجل حالياً.</p>}</section>}
   {tab==="settings"&&<section style={{background:"#fff",border:"1px solid #e6ebf2",borderRadius:17,padding:22,maxWidth:850}}><h2 style={{fontSize:18,marginTop:0}}>الإعدادات العامة للمنصة</h2><p style={{fontSize:13,color:"#8290a3",lineHeight:1.7}}>هذه الإعدادات تخص منصة MenuStore نفسها، ولا تغيّر بيانات المتاجر الفردية.</p><div style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(220px,1fr))",gap:16,marginTop:20}}><label><span style={label}>اسم المنصة</span><input style={field} value={settings.platformName||""} onChange={e=>SS({...settings,platformName:e.target.value})}/></label><label><span style={label}>بريد الدعم</span><input style={field} value={settings.supportEmail||""} onChange={e=>SS({...settings,supportEmail:e.target.value})}/></label><label><span style={label}>هاتف الدعم</span><input style={field} value={settings.supportPhone||""} onChange={e=>SS({...settings,supportPhone:e.target.value})}/></label><label><span style={label}>مدة الاشتراك الافتراضية (شهر)</span><input style={field} type="number" min="1" max="60" value={settings.defaultSubscriptionMonths||1} onChange={e=>SS({...settings,defaultSubscriptionMonths:Number(e.target.value)})}/></label></div><label style={{display:"flex",alignItems:"center",gap:10,marginTop:22,fontSize:13,fontWeight:700}}><input type="checkbox" checked={!!settings.maintenanceMode} onChange={e=>SS({...settings,maintenanceMode:e.target.checked})}/> وضع الصيانة: إيقاف ظهور المتاجر مؤقتاً مع إبقاء لوحة السوبر أدمن متاحة</label><label style={{display:"block",marginTop:16}}><span style={label}>رسالة الصيانة التي تظهر للزوار</span><input style={field} value={settings.maintenanceMessage||""} onChange={e=>SS({...settings,maintenanceMessage:e.target.value})} placeholder="نعمل على تحسين الخدمة، عودوا قريباً"/></label><button onClick={saveSettings} disabled={busy} style={{marginTop:22,padding:"12px 20px",border:0,borderRadius:11,background:"#172b49",color:"#fff",fontWeight:800,cursor:"pointer"}}>حفظ إعدادات المنصة</button></section>}
